INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_WARD_SAYINGS','primary text','The Sayings of the Desert Fathers: The Alphabetical Collection (Apophthegmata Patrum), trans. Benedicta Ward, Cistercian Publications, rev. ed. 1984','Early Christian monastic apophthegmata (Egyptian desert monasticism, 4th-5th c.)')
INSERT INTO _e VALUES
 ('ENT_DESERT_FATHERS','The Desert Fathers and Mothers','Saint collective','monastic collective','Christian','monasticism, asceticism, contemplative prayer','B','Collective hub for the abbas and ammas of 4th-5th c. Egyptian/Palestinian desert monasticism, whose sayings are preserved in the Apophthegmata Patrum (Sayings of the Desert Fathers).'),
 ('ENT_DESERT_PACHOMIUS','Pachomius the Great','Monk/saint','monastic founder','Christian','cenobitic monasticism, monastic rule','B','c.292-348; founder of cenobitic (communal) monasticism in the Egyptian Thebaid, author of the first monastic Rule; attested in his Lives (Bohairic/Greek) and the Apophthegmata tradition.'),
 ('ENT_DESERT_MACARIUS','Macarius the Great (Macarius the Egyptian)','Monk/saint','abba','Christian','asceticism, contemplative prayer','B','c.300-391; abba of the desert of Scetis, disciple of Anthony; one of the most heavily represented abbas in the alphabetical Apophthegmata Patrum.'),
 ('ENT_DESERT_EVAGRIUS','Evagrius Ponticus','Monk/theologian','abba','Christian','ascetic theology, contemplation, the eight thoughts (logismoi)','B','345-399; monk of the Kellia/Nitria, systematizer of desert ascetic teaching (Praktikos, Chapters on Prayer), originator of the eight evil thoughts later reworked as the seven deadly sins; condemned in the Origenist controversies.'),
 ('ENT_DESERT_CASSIAN','John Cassian','Monk/saint','monastic writer','Christian','monastic theology, transmission of desert teaching to the West','B','c.360-435; studied among the Egyptian desert monks, then transmitted their teaching to Latin monasticism through his Institutes and Conferences (Collationes); a key conduit of Evagrian thought to the West.'),
 ('ENT_DESERT_MOSES_BLACK','Moses the Black (Moses the Ethiopian)','Monk/saint','abba','Christian','asceticism, humility, repentance','B','c.330-405; former brigand turned abba of Scetis, exemplar of repentance and humility; attested in the Apophthegmata Patrum (Abba Moses). Homonym of the Israelite prophet Moses (ENT_ISR_MOSES) — distinct figure.'),
 ('ENT_DESERT_POEMEN','Poemen (Abba Poemen)','Monk/saint','abba','Christian','discernment, ascetic counsel','B','4th-5th c. abba of Scetis; the single most heavily quoted father in the alphabetical Apophthegmata Patrum, a touchstone for the editing of the collection.'),
 ('ENT_DESERT_ARSENIUS','Arsenius the Great','Monk/saint','abba','Christian','silence, withdrawal (hesychia), asceticism','B','c.354-450; Roman senatorial tutor who fled to the desert of Scetis, abba famed for radical silence and stillness; prominently attested in the Apophthegmata Patrum.'),
 ('ENT_DESERT_PAUL_THEBES','Paul of Thebes (Paul the First Hermit)','Hermit/saint','hermit','Christian','eremitic solitude, asceticism','C','c.227-341 per tradition; reputed first Christian hermit of the Egyptian desert, known chiefly through Jerome''s Vita Pauli; traditionally visited and venerated by Anthony near his death.'),
 ('ENT_DESERT_SYNCLETICA','Amma Syncletica of Alexandria','Nun/saint','amma','Christian','asceticism, spiritual direction','B','c.270-350; desert amma of Alexandria, one of the three women in the alphabetical Apophthegmata Patrum; subject of a Life attributed to (Pseudo-)Athanasius.'),
 ('ENT_DESERT_SARAH','Amma Sarah (Sarah of the Desert)','Nun/saint','amma','Christian','asceticism, spiritual combat','B','4th-5th c. desert amma; one of the three women included in the alphabetical Apophthegmata Patrum, famed for resisting the demon of fornication. Homonym of the matriarch Sarah (ENT_ISR_SARAH) — distinct figure.'),
 ('ENT_DESERT_THEODORA','Amma Theodora','Nun/saint','amma','Christian','asceticism, humility, discernment','B','4th-5th c. desert amma; one of the three women in the alphabetical Apophthegmata Patrum, associated with Archbishop Theophilus of Alexandria in her sayings.'),
 ('ENT_DESERT_PAMBO','Pambo (Abba Pambo)','Monk/saint','abba','Christian','silence, asceticism','B','c.303-373; abba of Nitria, teacher associated with Macarius and the Tall Brothers; noted for measured speech and gravity; attested in the Apophthegmata Patrum.'),
 ('ENT_DESERT_SISOES','Sisoes (Abba Sisoes)','Monk/saint','abba','Christian','compunction, humility, asceticism','B','d. c.429; abba who settled on Anthony''s inner mountain after Anthony''s death; exemplar of penthos (compunction) in the Apophthegmata Patrum.');
