INSERT INTO _r VALUES
 ('ENT_DESERT_PACHOMIUS','member_of','ENT_DESERT_FATHERS','high','Pachomius is a founding figure of Egyptian desert monasticism, counted among the desert fathers.'),
 ('ENT_DESERT_MACARIUS','member_of','ENT_DESERT_FATHERS','high','Macarius the Great is a leading abba of Scetis in the Apophthegmata Patrum.'),
 ('ENT_DESERT_EVAGRIUS','member_of','ENT_DESERT_FATHERS','high','Evagrius Ponticus was a monk of Nitria/Kellia and systematizer of desert ascetic teaching.'),
 ('ENT_DESERT_CASSIAN','member_of','ENT_DESERT_FATHERS','high','John Cassian lived among and transmitted the teaching of the Egyptian desert fathers.'),
 ('ENT_DESERT_MOSES_BLACK','member_of','ENT_DESERT_FATHERS','high','Moses the Black was an abba of Scetis represented in the Apophthegmata Patrum.'),
 ('ENT_DESERT_POEMEN','member_of','ENT_DESERT_FATHERS','high','Poemen is the most quoted abba in the alphabetical Apophthegmata Patrum.'),
 ('ENT_DESERT_ARSENIUS','member_of','ENT_DESERT_FATHERS','high','Arsenius the Great was an abba of Scetis in the Apophthegmata Patrum.'),
 ('ENT_DESERT_PAUL_THEBES','member_of','ENT_DESERT_FATHERS','high','Paul of Thebes is traditionally the first Christian desert hermit.'),
 ('ENT_DESERT_SYNCLETICA','member_of','ENT_DESERT_FATHERS','high','Amma Syncletica is one of the desert mothers in the Apophthegmata Patrum.'),
 ('ENT_DESERT_SARAH','member_of','ENT_DESERT_FATHERS','high','Amma Sarah is one of the three women in the alphabetical Apophthegmata Patrum.'),
 ('ENT_DESERT_THEODORA','member_of','ENT_DESERT_FATHERS','high','Amma Theodora is one of the desert mothers in the Apophthegmata Patrum.'),
 ('ENT_DESERT_PAMBO','member_of','ENT_DESERT_FATHERS','high','Pambo was an abba of Nitria in the Apophthegmata Patrum.'),
 ('ENT_DESERT_SISOES','member_of','ENT_DESERT_FATHERS','high','Sisoes was a desert abba who dwelt on Anthony''s mountain, attested in the Apophthegmata Patrum.'),
 ('ENT_SAINT_ANTHONY_ABBOT','member_of','ENT_DESERT_FATHERS','high','Anthony the Great (existing ENT_SAINT_ANTHONY_ABBOT), the father of monasticism, is the foremost of the desert fathers; cross-link, not duplicated.'),
 ('ENT_DESERT_FATHERS','embodies','ENT_MONASTICISM','high','The desert fathers and mothers collectively embody and originate Christian monasticism (existing ENT_MONASTICISM, a Ritual/social category — not a deity).'),
 ('ENT_DESERT_FATHERS','dwells_in','ENT_DESERT','medium','The desert fathers withdrew to and dwelt in the Egyptian/Palestinian desert (existing ENT_DESERT, a Place/environment category).'),
 ('ENT_DESERT_PACHOMIUS','embodies','ENT_MONASTICISM','high','Pachomius founded cenobitic (communal) monasticism, a core form of Christian monasticism (existing ENT_MONASTICISM, a Ritual/social category — not a deity).'),
 ('ENT_DESERT_MACARIUS','taught_by','ENT_SAINT_ANTHONY_ABBOT','medium','Tradition and the Apophthegmata present Macarius the Great as a disciple of Anthony the Great (existing ENT_SAINT_ANTHONY_ABBOT).'),
 ('ENT_DESERT_EVAGRIUS','taught_by','ENT_DESERT_MACARIUS','medium','Evagrius Ponticus was a disciple of Macarius the Great (and Macarius of Alexandria) at the Kellia/Nitria.'),
 ('ENT_DESERT_CASSIAN','transmits','ENT_DESERT_EVAGRIUS','high','John Cassian transmitted Evagrian ascetic teaching, notably the eight thoughts, to Latin monasticism through his Institutes and Conferences.'),
 ('ENT_DESERT_SISOES','taught_by','ENT_SAINT_ANTHONY_ABBOT','low','Sisoes settled on Anthony the Great''s inner mountain after Anthony''s death, presenting himself as heir to Anthony''s ascetic place and tradition.'),
 ('ENT_DESERT_PAMBO','taught_by','ENT_DESERT_MACARIUS','low','Pambo of Nitria is associated with the Macarian circle of Nitria/Kellia in the Apophthegmata tradition.'),
 ('ENT_DESERT_EVAGRIUS','opposed_by','ENT_DESERT_CASSIAN','low','Cassian transmitted Evagrian doctrine but tacitly distanced it from the Evagrian-Origenist speculation later condemned; a guarded reception rather than full endorsement.');
